use std::io::Read;
fn main() {
    let mut s = String::new(); std::io::stdin().read_to_string(&mut s).unwrap();
    let re = regex::bytes::Regex::new(r"\b|\B").unwrap();
    let mut ok = 0; let mut bad = 0;
    for line in s.lines() {
        let mut it = line.split('\t');
        let inp = hex(it.next().unwrap());
        let exp: Vec<String> = it.next().unwrap().split(',').map(|x| x.to_string()).collect();
        let mut pos: Vec<usize> = re.find_iter(&inp).map(|m| m.start()).collect();
        if pos.first() != Some(&0) { pos.insert(0,0); }
        if pos.last() != Some(&inp.len()) { pos.push(inp.len()); }
        let got: Vec<String> = pos.windows(2).map(|w| inp[w[0]..w[1]].iter().map(|b| format!("{:02x}", b)).collect()).collect();
        if got == exp { ok += 1 } else { bad += 1; println!("MISMATCH {:02x?} exp {:?} got {:?}", inp, exp, got); }
    }
    println!("ok={ok} bad={bad}");
}
fn hex(s: &str) -> Vec<u8> { (0..s.len()).step_by(2).map(|i| u8::from_str_radix(&s[i..i+2],16).unwrap()).collect() }
