{"command":"cd /workspace && cat > src/args.rs <<'EOF'
//! A small command line parser.
//!
//! The semantics mimic what the tool historically accepted: options can be
//! given as `--key value`, `--key=value`, `-k value`, `-k=value` or `-kvalue`,
//! values may be wrapped in matching quotes when attached to the key, and
//! single-letter flags can be combined (`-gj`).

use std::ffi::{OsStr, OsString};
use std::fmt;

pub enum ArgError {
    NoValue(&'static str),
    NonUtf8,
    Parse { value: String, cause: String },
}

impl fmt::Display for ArgError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            ArgError::NoValue(key) => {
                write!(f, "the '{}' option doesn't have an associated value", key)
            }
            ArgError::NonUtf8 => write!(f, "argument is not a UTF-8 string"),
            ArgError::Parse { value, cause } => write!(f, "failed to parse '{}': {}", value, cause),
        }
    }
}

pub struct Args {
    items: Vec<OsString>,
}

struct Found {
    value: String,
    index: usize,
    two_args: bool,
}

fn has_prefix_eq(arg: &OsStr, key: &str) -> bool {
    match arg.to_str() {
        Some(s) => s.len() > key.len() && s.starts_with(key) && s.as_bytes()[key.len()] == b'=',
        None => false,
    }
}

fn has_short_prefix(arg: &OsStr, key: &str) -> bool {
    if key.starts_with("--") {
        return false;
    }
    match arg.to_str() {
        Some(s) => s.starts_with(key),
        None => false,
    }
}

impl Args {
    pub fn new(items: Vec<OsString>) -> Self {
        Args { items }
    }

    pub fn into_remaining(self) -> Vec<OsString> {
        self.items
    }

    fn exact(&self, keys: &[&'static str]) -> Option<(usize, &'static str)> {
        for key in keys {
            if let Some(i) = self.items.iter().position(|a| a.as_os_str() == OsStr::new(key)) {
                return Some((i, key));
            }
        }
        None
    }

    fn attached(&self, keys: &[&'static str]) -> Option<(usize, &'static str)> {
        let long = keys.iter().find(|k| k.starts_with("--"));
        let short = keys.iter().find(|k| !k.starts_with("--"));
        if let Some(long) = long {
            if let Some(i) = self.items.iter().position(|a| has_prefix_eq(a, long)) {
                return Some((i, long));
            }
        }
        if let Some(short) = short {
            if let Some(i) = self.items.iter().position(|a| has_prefix_eq(a, short)) {
                return Some((i, short));
            }
            if let Some(i) = self.items.iter().position(|a| has_short_prefix(a, short)) {
                return Some((i, short));
            }
        }
        None
    }

    /// Check for the presence of a flag, removing it.
    pub fn flag(&mut self, keys: &[&'static str]) -> bool {
        if let Some((i, _)) = self.exact(keys) {
            self.items.remove(i);
            return true;
        }
        let short = match keys.iter().find(|k| !k.starts_with("--")) {
            Some(s) if s.len() == 2 => *s,
            _ => return false,
        };
        let letter = &short[1..2];
        for n in 0..self.items.len() {
            if let Some(s) = self.items[n].to_str() {
                if s.starts_with('-') && !s.starts_with("--") && s.contains(letter) {
                    if s.len() == 2 {
                        self.items.remove(n);
                    } else {
                        let replaced = s.replacen(letter, "", 1);
                        self.items[n] = OsString::from(replaced);
                    }
                    return true;
                }
            }
        }
        false
    }

    fn find(&self, keys: &[&'static str]) -> Result<Option<Found>, ArgError> {
        if let Some((i, key)) = self.exact(keys) {
            let v = match self.items.get(i + 1) {
                Some(v) => v,
                None => return Err(ArgError::NoValue(key)),
            };
            let v = v.to_str().ok_or(ArgError::NonUtf8)?;
            return Ok(Some(Found { value: v.to_string(), index: i, two_args: true }));
        }
        if let Some((i, key)) = self.attached(keys) {
            let s = self.items[i].to_str().ok_or(ArgError::NonUtf8)?;
            let b = s.as_bytes();
            let mut start = key.len();
            let mut end = s.len();
            if b.get(start) == Some(&b'=') {
                start += 1;
            }
            if let Some(&c) = b.get(start) {
                if c == b'"' || c == b'\'' {
                    start += 1;
                    if b.len() > start && b[b.len() - 1] == c {
                        end -= 1;
                    } else {
                        return Err(ArgError::NoValue(key));
                    }
                }
            }
            if end <= start {
                return Err(ArgError::NoValue(key));
            }
            return Ok(Some(Found { value: s[start..end].to_string(), index: i, two_args: false }));
        }
        Ok(None)
    }

    fn take(&mut self, found: &Found) {
        self.items.remove(found.index);
        if found.two_args {
            self.items.remove(found.index);
        }
    }

    /// Fetch the value of an option, converting it with `parse`.
    pub fn value<T, F>(&mut self, keys: &[&'static str], parse: F) -> Result<Option<T>, ArgError>
    where
        F: FnOnce(&str) -> Result<T, String>,
    {
        match self.find(keys)? {
            None => Ok(None),
            Some(found) => {
                let parsed = parse(&found.value).map_err(|cause| ArgError::Parse {
                    value: found.value.clone(),
                    cause,
                })?;
                self.take(&found);
                Ok(Some(parsed))
            }
        }
    }

    /// Like `value`, but a missing value is not an error: the option is
    /// simply left where it is (and will be reported as unexpected).
    /// An explicitly empty `--key=` is accepted as an empty value.
    pub fn lenient_value(&mut self, key: &'static str) -> Result<Option<String>, ArgError> {
        match self.find(&[key]) {
            Ok(Some(found)) => {
                self.take(&found);
                Ok(Some(found.value))
            }
            Ok(None) => Ok(None),
            Err(ArgError::NoValue(_)) => {
                let empty = format!("{}=", key);
                if let Some(i) = self.items.iter().position(|a| a.as_os_str() == OsStr::new(&empty)) {
                    self.items.remove(i);
                    Ok(Some(String::new()))
                } else {
                    Ok(None)
                }
            }
            Err(e) => Err(e),
        }
    }
}
EOF
