use std::fs::File;
use std::io::{self, BufRead, BufReader, Read, Write};
use std::os::unix::io::AsRawFd;
use std::path::Path;

use crate::fatal::main_error;

pub struct Out {
    w: io::BufWriter<io::StdoutLock<'static>>,
}

fn io_failure(e: io::Error) -> ! {
    if e.kind() == io::ErrorKind::BrokenPipe {
        std::process::exit(0);
    }
    main_error(&e.to_string());
}

impl Out {
    pub fn new() -> Self {
        Out { w: io::BufWriter::with_capacity(64 * 1024, io::stdout().lock()) }
    }

    #[inline]
    pub fn write(&mut self, b: &[u8]) {
        if let Err(e) = self.w.write_all(b) {
            io_failure(e);
        }
    }

    #[inline]
    pub fn byte(&mut self, b: u8) {
        self.write(&[b]);
    }

    pub fn flush(&mut self) {
        if let Err(e) = self.w.flush() {
            io_failure(e);
        }
    }

    /// Flush what was produced so far and terminate with `Error: <msg>`.
    pub fn fail(&mut self, msg: &str) -> ! {
        self.flush();
        main_error(msg);
    }
}

// ---------------------------------------------------------------------------
// memory mapping

const PROT_READ: i32 = 1;
const MAP_SHARED: i32 = 1;

extern "C" {
    fn mmap(addr: *mut u8, len: usize, prot: i32, flags: i32, fd: i32, off: i64) -> *mut u8;
}

pub struct Mapped {
    ptr: *const u8,
    len: usize,
    _file: File,
}

impl Mapped {
    pub fn as_slice(&self) -> &[u8] {
        if self.len == 0 {
            &[]
        } else {
            unsafe { std::slice::from_raw_parts(self.ptr, self.len) }
        }
    }
}

fn map_file(file: File) -> io::Result<Mapped> {
    let len = file.metadata()?.len() as usize;
    let map_len = len.max(1);
    let ptr = unsafe { mmap(std::ptr::null_mut(), map_len, PROT_READ, MAP_SHARED, file.as_raw_fd(), 0) };
    if ptr as isize == -1 {
        return Err(io::Error::last_os_error());
    }
    Ok(Mapped { ptr, len, _file: file })
}

// ---------------------------------------------------------------------------
// input

pub enum Input {
    Mapped(Mapped),
    Reader(Box<dyn BufRead>),
}

pub fn open_input(path: Option<&Path>, no_mmap: bool) -> Input {
    match path {
        None => Input::Reader(Box::new(BufReader::with_capacity(64 * 1024, io::stdin()))),
        Some(p) => {
            let file = match File::open(p) {
                Ok(f) => f,
                Err(e) => main_error(&format!("{}.\nWas attempting to read {:?}", e, p)),
            };
            if no_mmap {
                Input::Reader(Box::new(BufReader::with_capacity(64 * 1024, file)))
            } else {
                match map_file(file) {
                    Ok(m) => Input::Mapped(m),
                    Err(e) => main_error(&e.to_string()),
                }
            }
        }
    }
}

impl Input {
    pub fn read_all(self) -> Vec<u8> {
        match self {
            Input::Mapped(m) => m.as_slice().to_vec(),
            Input::Reader(mut r) => {
                let mut v = Vec::new();
                if let Err(e) = r.read_to_end(&mut v) {
                    main_error(&e.to_string());
                }
                v
            }
        }
    }

    pub fn records(self, eol: u8) -> Records {
        match self {
            Input::Mapped(m) => Records { src: Src::Mapped(m, 0), eol, buf: Vec::new() },
            Input::Reader(r) => Records { src: Src::Reader(r), eol, buf: Vec::new() },
        }
    }
}

enum Src {
    Mapped(Mapped, usize),
    Reader(Box<dyn BufRead>),
}

/// Iterates over the records of the input (without their terminator).
pub struct Records {
    src: Src,
    eol: u8,
    buf: Vec<u8>,
}

impl Records {
    pub fn next_record(&mut self) -> Option<&[u8]> {
        match &mut self.src {
            Src::Mapped(m, pos) => {
                let data = m.as_slice();
                if *pos >= data.len() {
                    return None;
                }
                let start = *pos;
                match memchr::memchr(self.eol, &data[start..]) {
                    Some(i) => {
                        *pos = start + i + 1;
                        Some(&data[start..start + i])
                    }
                    None => {
                        *pos = data.len();
                        Some(&data[start..])
                    }
                }
            }
            Src::Reader(r) => {
                self.buf.clear();
                match r.read_until(self.eol, &mut self.buf) {
                    Ok(0) => None,
                    Ok(_) => {
                        if self.buf.last() == Some(&self.eol) {
                            self.buf.pop();
                        }
                        Some(&self.buf[..])
                    }
                    Err(e) => main_error(&e.to_string()),
                }
            }
        }
    }
}
