//! Command line options: parsing, validation and derived settings.

use std::ffi::OsString;
use std::path::PathBuf;

use regex::bytes::Regex;

use crate::args::{ArgError, Args};
use crate::bounds::{has_fillers, parse_bounds_list, Item};
use crate::fatal::runtime_error;

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum BoundsType {
    Fields,
    Bytes,
    Chars,
    Lines,
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Trim {
    Left,
    Right,
    Both,
}

pub struct Opt {
    pub bounds_type: BoundsType,
    pub bounds: Vec<Item>,
    /// Literal delimiter (used when `regex` is None).
    pub delimiter: Vec<u8>,
    pub regex: Option<Regex>,
    /// `(?:<regex>)+`, used to compress sequences of delimiters.
    pub regex_plus: Option<Regex>,
    pub greedy: bool,
    pub compress: bool,
    pub only_delimited: bool,
    pub complement: bool,
    pub json: bool,
    pub join: bool,
    /// Effective replacement for the delimiter (user provided, or implied).
    pub replace: Option<Vec<u8>>,
    pub trim: Option<Trim>,
    pub fallback_oob: Option<Vec<u8>>,
    pub fixed_memory: Option<usize>,
    pub eol: u8,
    pub path: Option<PathBuf>,
    pub no_mmap: bool,
}

fn or_exit<T>(r: Result<T, ArgError>) -> T {
    match r {
        Ok(v) => v,
        Err(e) => {
            eprintln!("{}", e);
            std::process::exit(1);
        }
    }
}

fn parse_trim(s: &str) -> Result<Trim, String> {
    match s {
        "l" | "L" => Ok(Trim::Left),
        "r" | "R" => Ok(Trim::Right),
        "b" | "B" => Ok(Trim::Both),
        _ => Err("Valid trim values are (l|L)eft, (r|R)ight, (b|B)oth".to_string()),
    }
}

fn parse_usize(s: &str) -> Result<usize, String> {
    s.parse::<usize>().map_err(|e| e.to_string())
}

fn string(s: &str) -> Result<String, String> {
    Ok(s.to_string())
}

pub fn parse(raw: Vec<OsString>) -> Opt {
    let mut a = Args::new(raw);

    if a.flag(&["-h", "--help"]) {
        crate::print_help();
    }
    if a.flag(&["-V", "--version"]) {
        crate::print_version();
    }

    let fields = or_exit(a.value(&["-f", "--fields"], parse_bounds_list));
    let chars = or_exit(a.value(&["-c", "--characters"], parse_bounds_list));
    let bytes = or_exit(a.value(&["-b", "--bytes"], parse_bounds_list));
    let lines = or_exit(a.value(&["-l", "--lines"], parse_bounds_list));
    let delimiter = or_exit(a.value(&["-d", "--delimiter"], string));
    let greedy = a.flag(&["-g", "--greedy-delimiter"]);
    let replace = or_exit(a.value(&["-r", "--replace-delimiter"], string));
    let fixed_memory = or_exit(a.value(&["-M", "--fixed-memory"], parse_usize));
    let join_flag = a.flag(&["-j", "--join"]);
    let no_join = a.flag(&["--no-join"]);
    let json = a.flag(&["--json"]);
    let regex_str = or_exit(a.value(&["-e", "--regex"], string));
    let compress = a.flag(&["-p", "--compress-delimiter"]);
    let only_delimited = a.flag(&["-s", "--only-delimited"]);
    let complement = a.flag(&["-m", "--complement"]);
    let trim = or_exit(a.value(&["-t", "--trim"], parse_trim));
    let zero_terminated = a.flag(&["-z", "--zero-terminated"]);
    let fallback_oob = or_exit(a.lenient_value("--fallback-oob"));
    let no_mmap = a.flag(&["--no-mmap"]);

    let remaining = a.into_remaining();
    if remaining.len() > 1
        || (remaining.len() == 1 && remaining[0].to_string_lossy().starts_with('-'))
    {
        eprintln!("tuc: unexpected arguments: {:?}", remaining);
        eprintln!("Try 'tuc --help' for more information.");
        std::process::exit(1);
    }
    let path: Option<PathBuf> = remaining.first().and_then(|p| p.to_str()).map(PathBuf::from);

    let (bounds_type, bounds) = if let Some(f) = fields {
        (BoundsType::Fields, f)
    } else if let Some(b) = bytes {
        (BoundsType::Bytes, b)
    } else if let Some(c) = chars {
        (BoundsType::Chars, c)
    } else if let Some(l) = lines {
        (BoundsType::Lines, l)
    } else {
        (BoundsType::Fields, parse_bounds_list("1:").unwrap())
    };

    // ---- validations ------------------------------------------------------

    if let Some(p) = &path {
        if !p.exists() {
            runtime_error(&format!("The file {:?} does not exist", p));
        }
        if !p.is_file() {
            runtime_error(&format!("The path {:?} is not a file", p));
        }
    }

    if fixed_memory == Some(0) {
        runtime_error("--fixed-memory cannot be 0");
    }

    if join_flag && no_join {
        runtime_error("It's not possible to use --join and --no-join simultaneously");
    }
    if json && no_join {
        runtime_error("Using both --json and --no-join is not permitted");
    }
    if replace.is_some() && no_join {
        runtime_error("You can't pass --no-join when using --replace, which implies --join");
    }
    if json && replace.is_some() {
        runtime_error("The use of --replace with --json is not supported");
    }
    if json && !matches!(bounds_type, BoundsType::Fields | BoundsType::Chars) {
        runtime_error("--json support is available only for --fields and --characters");
    }

    let mut regex = None;
    let mut regex_plus = None;
    if bounds_type != BoundsType::Chars {
        if let Some(re) = &regex_str {
            match Regex::new(re) {
                Ok(r) => regex = Some(r),
                Err(e) => runtime_error(&format!("The regular expression is malformed. {}", e)),
            }
            if compress {
                regex_plus = Regex::new(&format!("(?:{})+", re)).ok();
            }
        }
    }

    if json && has_fillers(&bounds) {
        runtime_error("Cannot format fields when using --json");
    }

    let join = join_flag || json || replace.is_some() || (bounds_type == BoundsType::Lines && !no_join);

    if regex.is_some() && join && replace.is_none() && !json {
        runtime_error("Cannot use --regex and --join without --replace-delimiter");
    }
    if regex.is_some() && compress && replace.is_none() && !json {
        runtime_error("Cannot use --regex and --compress-delimiter without --replace-delimiter");
    }
    if compress && !matches!(bounds_type, BoundsType::Fields | BoundsType::Lines) {
        runtime_error("Delimiters can be compressed only with --fields and --lines");
    }

    // ---- derived settings -------------------------------------------------

    let delimiter: Vec<u8> = match bounds_type {
        BoundsType::Lines => b"\n".to_vec(),
        BoundsType::Chars | BoundsType::Bytes => Vec::new(),
        BoundsType::Fields => delimiter.map(|d| d.into_bytes()).unwrap_or_else(|| b"\t".to_vec()),
    };

    let replace = if json {
        Some(b",".to_vec())
    } else {
        replace.map(|r| r.into_bytes())
    };

    Opt {
        bounds_type,
        bounds,
        delimiter,
        regex,
        regex_plus,
        greedy,
        compress,
        only_delimited,
        complement,
        json,
        join,
        replace,
        trim,
        fallback_oob: fallback_oob.map(|s| s.into_bytes()),
        fixed_memory,
        eol: if zero_terminated { 0 } else { b'\n' },
        path,
        no_mmap,
    }
}
EOF
echo ok"}

