//! Per-record cutting of fields / characters (and lines, when they cannot be
//! streamed).

use std::borrow::Cow;

use memchr::memmem;
use regex::bytes::Regex;

use crate::bounds::{resolve_clamped, resolve_strict, ResolveError, Side, UserBounds, Item};
use crate::fatal::{panic_empty_list, panic_no_count_complement, panic_no_count_unpack};
use crate::io::{Out, Records};
use crate::options::{BoundsType, Opt, Trim};

/// How a delimiter is matched inside a record.
enum Matcher<'a> {
    Literal(&'a [u8]),
    Regex(&'a Regex),
}

fn literal_matches(hay: &[u8], needle: &[u8], out: &mut Vec<(usize, usize)>) {
    if needle.is_empty() {
        for i in 0..=hay.len() {
            out.push((i, i));
        }
    } else {
        for i in memmem::find_iter(hay, needle) {
            out.push((i, i + needle.len()));
        }
    }
}

impl<'a> Matcher<'a> {
    fn matches(&self, hay: &[u8], out: &mut Vec<(usize, usize)>) {
        out.clear();
        match self {
            Matcher::Literal(d) => literal_matches(hay, d, out),
            Matcher::Regex(re) => {
                for m in re.find_iter(hay) {
                    out.push((m.start(), m.end()));
                }
            }
        }
    }

    fn replace<'t>(&self, text: &'t [u8], repl: &[u8]) -> Cow<'t, [u8]> {
        match self {
            Matcher::Literal(d) => {
                let mut ms = Vec::new();
                literal_matches(text, d, &mut ms);
                if ms.is_empty() {
                    return Cow::Borrowed(text);
                }
                let mut v = Vec::with_capacity(text.len() + ms.len() * repl.len());
                let mut last = 0;
                for (s, e) in ms {
                    v.extend_from_slice(&text[last..s]);
                    v.extend_from_slice(repl);
                    last = e;
                }
                v.extend_from_slice(&text[last..]);
                Cow::Owned(v)
            }
            Matcher::Regex(re) => re.replace_all(text, repl),
        }
    }
}

fn trim_literal(mut line: &[u8], d: &[u8], trim: Trim) -> &[u8] {
    if d.is_empty() {
        return line;
    }
    if matches!(trim, Trim::Left | Trim::Both) {
        while line.starts_with(d) {
            line = &line[d.len()..];
        }
    }
    if matches!(trim, Trim::Right | Trim::Both) {
        while line.ends_with(d) {
            line = &line[..line.len() - d.len()];
        }
    }
    line
}

fn trim_regex<'l>(line: &'l [u8], re: &Regex, trim: Trim) -> &'l [u8] {
    let ms: Vec<(usize, usize)> = re.find_iter(line).map(|m| (m.start(), m.end())).collect();
    let mut start = 0;
    let mut end = line.len();
    if matches!(trim, Trim::Left | Trim::Both) {
        for &(s, e) in &ms {
            if s == start {
                start = e;
            } else {
                break;
            }
        }
    }
    if matches!(trim, Trim::Right | Trim::Both) {
        for &(s, e) in ms.iter().rev() {
            if e == end && s >= start {
                end = s;
            } else {
                break;
            }
        }
    }
    if start > end {
        return &line[..0];
    }
    &line[start..end]
}

/// Keep only the first delimiter of each sequence of adjacent delimiters.
fn compress_literal<'l>(line: &'l [u8], d: &[u8]) -> Cow<'l, [u8]> {
    if d.is_empty() {
        return Cow::Borrowed(line);
    }
    let mut ms = Vec::new();
    literal_matches(line, d, &mut ms);
    let mut changed = false;
    for w in ms.windows(2) {
        if w[1].0 == w[0].1 {
            changed = true;
            break;
        }
    }
    if !changed {
        return Cow::Borrowed(line);
    }
    let mut v = Vec::with_capacity(line.len());
    let mut last = 0;
    let mut prev_end: Option<usize> = None;
    for (s, e) in ms {
        if prev_end == Some(s) {
            // adjacent: drop this occurrence
            v.extend_from_slice(&line[last..s]);
            last = e;
        }
        prev_end = Some(e);
    }
    v.extend_from_slice(&line[last..]);
    Cow::Owned(v)
}

/// Shared, per-run state for record processing.
pub struct Cutter<'o> {
    opt: &'o Opt,
    chars_re: Option<Regex>,
    fast: bool,
    expand: bool,
    matches: Vec<(usize, usize)>,
    fields: Vec<(usize, usize)>,
    items_buf: Vec<Item>,
}

enum Entry<'b> {
    Filler(&'b [u8]),
    Field(usize),
    Single(&'b UserBounds),
}

impl<'o> Cutter<'o> {
    pub fn new(opt: &'o Opt) -> Self {
        let chars = opt.bounds_type == BoundsType::Chars;
        let fast = opt.bounds_type == BoundsType::Fields
            && opt.regex.is_none()
            && opt.delimiter.len() == 1
            && !opt.greedy
            && !opt.compress
            && opt.replace.is_none()
            && !opt.complement
            && !opt.json;
        Cutter {
            opt,
            chars_re: if chars { Some(Regex::new(r"\b|\B").unwrap()) } else { None },
            fast,
            expand: chars || opt.json,
            matches: Vec::new(),
            fields: Vec::new(),
            items_buf: Vec::new(),
        }
    }

    pub fn run(&mut self, mut records: Records, out: &mut Out) {
        let eol = self.opt.eol;
        while let Some(rec) = records.next_record() {
            let mut line = rec;
            if eol == b'\n' && line.last() == Some(&b'\r') {
                line = &line[..line.len() - 1];
            }
            if let Err(msg) = self.process(line, out) {
                out.fail(&msg);
            }
        }
        out.flush();
    }

    fn process(&mut self, line: &[u8], out: &mut Out) -> Result<(), String> {
        let opt = self.opt;
        let chars = opt.bounds_type == BoundsType::Chars;

        // trim
        let mut line: &[u8] = line;
        if let (Some(t), false) = (opt.trim, chars) {
            line = match &opt.regex {
                Some(re) => trim_regex(line, re, t),
                None => trim_literal(line, &opt.delimiter, t),
            };
        }

        if line.is_empty() {
            if !opt.only_delimited {
                out.byte(opt.eol);
            }
            return Ok(());
        }

        // compress
        let mut compressed_delim: Option<&[u8]> = None;
        let line: Cow<[u8]> = if opt.compress && !chars {
            match (&opt.regex, &opt.regex_plus) {
                (Some(_), Some(plus)) => {
                    let repl = opt.replace.as_deref().unwrap_or(b"");
                    compressed_delim = Some(repl);
                    plus.replace_all(line, repl)
                }
                _ => compress_literal(line, &opt.delimiter),
            }
        } else {
            Cow::Borrowed(line)
        };
        let line: &[u8] = &line;

        // locate delimiters
        let split_matcher = if chars {
            Matcher::Regex(self.chars_re.as_ref().unwrap())
        } else if let Some(d) = compressed_delim {
            Matcher::Literal(d)
        } else if let Some(re) = &opt.regex {
            Matcher::Regex(re)
        } else {
            Matcher::Literal(&opt.delimiter)
        };
        let mut matches = std::mem::take(&mut self.matches);
        split_matcher.matches(line, &mut matches);

        self.fields.clear();
        if chars {
            let mut prev = 0usize;
            for &(s, _) in &matches {
                if s > prev {
                    self.fields.push((prev, s));
                    prev = s;
                }
            }
            if line.len() > prev {
                self.fields.push((prev, line.len()));
            }
        } else {
            if opt.greedy && matches.len() > 1 {
                let mut merged: Vec<(usize, usize)> = Vec::with_capacity(matches.len());
                for &(s, e) in &matches {
                    if let Some(last) = merged.last_mut() {
                        if last.1 == s {
                            last.1 = e;
                            continue;
                        }
                    }
                    merged.push((s, e));
                }
                matches = merged;
            }
            if opt.only_delimited && matches.is_empty() {
                self.matches = matches;
                return Ok(());
            }
            let mut start = 0;
            for &(s, e) in &matches {
                self.fields.push((start, s));
                start = e;
            }
            self.fields.push((start, line.len()));
        }
        self.matches = matches;

        // the matcher used to replace delimiters in the output
        let out_matcher = if chars {
            None
        } else if let Some(re) = &opt.regex {
            Some(Matcher::Regex(re))
        } else {
            Some(Matcher::Literal(&opt.delimiter))
        };

        // complement
        let n = self.fields.len();
        let items: &[Item] = if opt.complement {
            let mut v = std::mem::take(&mut self.items_buf);
            v.clear();
            for item in &opt.bounds {
                match item {
                    Item::Filler(f) => v.push(Item::Filler(f.clone())),
                    Item::Bound(b) => {
                        let (s, e) = match resolve_strict(b, n) {
                            Ok(r) => r,
                            Err(ResolveError::OutOfBounds(_)) => panic_no_count_complement(),
                            Err(ResolveError::LeftGreater) => continue,
                        };
                        if s > 0 {
                            v.push(Item::Bound(UserBounds::new(Side::Some(1), Side::Some(s as i64))));
                        }
                        if e + 1 < n {
                            v.push(Item::Bound(UserBounds::new(Side::Some(e as i64 + 2), Side::Continue)));
                        }
                    }
                }
            }
            if !v.iter().any(|i| matches!(i, Item::Bound(_))) {
                self.items_buf = v;
                return Err("the complement is empty".to_string());
            }
            self.items_buf = v;
            &self.items_buf
        } else {
            &opt.bounds
        };

        let join_delim: &[u8] = match &opt.replace {
            Some(r) => r,
            None => {
                if chars {
                    b""
                } else {
                    &opt.delimiter
                }
            }
        };

        let fields = &self.fields;
        let field_text = |i: usize| -> &[u8] { &line[fields[i].0..fields[i].1] };

        let emit = |out: &mut Out, text: &[u8]| {
            if opt.json {
                out.byte(b'"');
                let t = match &out_matcher {
                    Some(m) => m.replace(text, b","),
                    None => Cow::Borrowed(text),
                };
                json_escape(out, &t);
                out.byte(b'"');
            } else {
                match (&opt.replace, &out_matcher) {
                    (Some(r), Some(m)) => {
                        let t = m.replace(text, r);
                        out.write(&t);
                    }
                    _ => out.write(text),
                }
            }
        };

        if self.expand {
            // build the list of entries
            let has_ranges = items.iter().any(|i| matches!(i, Item::Bound(b) if !b.is_single()));
            let mut entries: Vec<Entry> = Vec::with_capacity(items.len());
            if has_ranges {
                for item in items {
                    match item {
                        Item::Filler(f) => entries.push(Entry::Filler(f)),
                        Item::Bound(b) => match resolve_strict(b, n) {
                            Ok((s, e)) => {
                                for i in s..=e {
                                    entries.push(Entry::Field(i));
                                }
                            }
                            Err(ResolveError::OutOfBounds(_)) => panic_no_count_unpack(),
                            Err(ResolveError::LeftGreater) => {}
                        },
                    }
                }
                if !entries.iter().any(|e| matches!(e, Entry::Field(_))) {
                    panic_empty_list();
                }
            } else {
                for item in items {
                    match item {
                        Item::Filler(f) => entries.push(Entry::Filler(f)),
                        Item::Bound(b) => entries.push(Entry::Single(b)),
                    }
                }
            }
            let last_bound = entries.iter().rposition(|e| !matches!(e, Entry::Filler(_)));
            if opt.json {
                out.byte(b'[');
            }
            for (i, entry) in entries.iter().enumerate() {
                match entry {
                    Entry::Filler(f) => out.write(f),
                    Entry::Field(k) => emit(out, field_text(*k)),
                    Entry::Single(b) => match resolve_strict(b, n) {
                        Ok((s, _)) => emit(out, field_text(s)),
                        Err(err) => match b.fallback.as_ref().or(opt.fallback_oob.as_ref()) {
                            Some(fb) => emit(out, fb),
                            None => return Err(err.to_string()),
                        },
                    },
                }
                if opt.join && !matches!(entry, Entry::Filler(_)) && Some(i) != last_bound {
                    out.write(join_delim);
                }
            }
            if opt.json {
                out.byte(b']');
            }
            out.byte(opt.eol);
            return Ok(());
        }

        let last_bound = items.iter().rposition(|i| matches!(i, Item::Bound(_)));
        for (i, item) in items.iter().enumerate() {
            match item {
                Item::Filler(f) => out.write(f),
                Item::Bound(b) => {
                    let r = if self.fast { resolve_clamped(b, n) } else { resolve_strict(b, n) };
                    match r {
                        Ok((s, e)) => emit(out, &line[fields[s].0..fields[e].1]),
                        Err(err) => match b.fallback.as_ref().or(opt.fallback_oob.as_ref()) {
                            Some(fb) => emit(out, fb),
                            None => return Err(err.to_string()),
                        },
                    }
                    if opt.join && Some(i) != last_bound {
                        out.write(join_delim);
                    }
                }
            }
        }
        out.byte(opt.eol);
        Ok(())
    }
}

pub fn json_escape(out: &mut Out, text: &[u8]) {
    const HEX: &[u8; 16] = b"0123456789abcdef";
    let mut last = 0;
    for (i, &c) in text.iter().enumerate() {
        let esc: Option<&[u8]> = match c {
            b'"' => Some(b"\\\""),
            b'\\' => Some(b"\\\\"),
            0x08 => Some(b"\\b"),
            0x0c => Some(b"\\f"),
            b'\n' => Some(b"\\n"),
            b'\r' => Some(b"\\r"),
            b'\t' => Some(b"\\t"),
            0..=0x1f => None,
            _ => continue,
        };
        out.write(&text[last..i]);
        match esc {
            Some(e) => out.write(e),
            None => {
                out.write(b"\\u00");
                out.byte(HEX[(c >> 4) as usize]);
                out.byte(HEX[(c & 0xf) as usize]);
            }
        }
        last = i + 1;
    }
    out.write(&text[last..]);
}
