//! Top level dispatch, plus the modes that do not work record by record:
//! bytes, streamed lines and fixed-memory streaming.

use crate::bounds::{resolve_clamped, Item, Side, UserBounds};
use crate::cut::Cutter;
use crate::fatal::runtime_error;
use crate::io::{open_input, Out, Records};
use crate::options::{BoundsType, Opt};

pub fn run(opt: Opt) {
    if opt.fixed_memory.is_some() {
        check_stream_opt(&opt);
        let input = open_input(opt.path.as_deref(), opt.no_mmap);
        let mut out = Out::new();
        stream_fields(&opt, input.records(opt.eol), &mut out);
        return;
    }

    match opt.bounds_type {
        BoundsType::Bytes => {
            let input = open_input(opt.path.as_deref(), opt.no_mmap);
            let mut out = Out::new();
            cut_bytes(&opt, &input.read_all(), &mut out);
        }
        BoundsType::Lines if lines_are_forward(&opt.bounds) && !opt.compress && !opt.complement => {
            let input = open_input(opt.path.as_deref(), opt.no_mmap);
            let mut out = Out::new();
            stream_lines(&opt, input.records(opt.eol), &mut out);
        }
        _ => {
            let input = open_input(opt.path.as_deref(), opt.no_mmap);
            let mut out = Out::new();
            let mut cutter = Cutter::new(&opt);
            cutter.run(input.records(opt.eol), &mut out);
        }
    }
}

fn positive(side: Side) -> bool {
    match side {
        Side::Some(v) => v > 0,
        Side::Continue => true,
    }
}

fn right_value(side: Side) -> i64 {
    match side {
        Side::Some(v) => v,
        Side::Continue => i64::MAX,
    }
}

fn bounds_iter(items: &[Item]) -> impl Iterator<Item = &UserBounds> {
    items.iter().filter_map(|i| match i {
        Item::Bound(b) => Some(b),
        Item::Filler(_) => None,
    })
}

/// Lines can be streamed when bounds are positive and in ascending order.
fn lines_are_forward(items: &[Item]) -> bool {
    let mut prev_r: i64 = 0;
    for b in bounds_iter(items) {
        if !positive(b.l) || !positive(b.r) {
            return false;
        }
        if b.left() < prev_r {
            return false;
        }
        prev_r = right_value(b.r);
    }
    true
}

// ---------------------------------------------------------------------------
// bytes

fn cut_bytes(opt: &Opt, data: &[u8], out: &mut Out) {
    if data.is_empty() {
        return;
    }
    let n = data.len();
    for item in &opt.bounds {
        match item {
            Item::Filler(f) => out.write(f),
            Item::Bound(b) => match resolve_clamped(b, n) {
                Ok((s, e)) => out.write(&data[s..=e]),
                Err(err) => out.fail(&err.to_string()),
            },
        }
    }
    out.flush();
}

// ---------------------------------------------------------------------------
// streamed lines

/// Lazily reads lines, remembering the last one read.
struct LineCursor {
    records: Records,
    /// number of lines read so far
    count: i64,
    current: Vec<u8>,
    eof: bool,
}

impl LineCursor {
    /// Make line `k` (1-based) the current one. Returns false if it does not exist.
    fn goto(&mut self, k: i64) -> bool {
        if k == self.count && k > 0 {
            return true;
        }
        while self.count < k {
            if self.eof {
                return false;
            }
            match self.records.next_record() {
                Some(r) => {
                    self.current.clear();
                    self.current.extend_from_slice(r);
                    self.count += 1;
                }
                None => {
                    self.eof = true;
                    return false;
                }
            }
        }
        self.count == k
    }
}

fn stream_lines(opt: &Opt, records: Records, out: &mut Out) {
    let eol = opt.eol;
    let mut cur = LineCursor { records, count: 0, current: Vec::new(), eof: false };
    let items = &opt.bounds;
    let n_items = items.len();
    'items: for (i, item) in items.iter().enumerate() {
        match item {
            Item::Filler(f) => out.write(f),
            Item::Bound(b) => {
                let l = b.left();
                match b.r {
                    Side::Continue => {
                        let mut k = l;
                        let mut first = true;
                        while cur.goto(k) {
                            if !first {
                                out.byte(eol);
                            }
                            first = false;
                            out.write(&cur.current);
                            k += 1;
                        }
                        break 'items;
                    }
                    Side::Some(r) => {
                        let mut k = l;
                        while k <= r {
                            if !cur.goto(k) {
                                out.fail(&format!("Out of bounds: {}", b));
                            }
                            out.write(&cur.current);
                            if k < r {
                                out.byte(eol);
                            }
                            k += 1;
                        }
                    }
                }
            }
        }
        if opt.join && i + 1 < n_items {
            out.byte(eol);
        }
    }
    out.byte(eol);
    out.flush();
}

// ---------------------------------------------------------------------------
// fixed memory streaming

fn check_stream_opt(opt: &Opt) {
    if opt.delimiter.len() != 1 {
        runtime_error("Delimiter must be 1 byte wide for FastOpt");
    }
    if opt.bounds_type != BoundsType::Fields
        || opt.regex.is_some()
        || opt.only_delimited
        || opt.trim.is_some()
        || opt.greedy
        || opt.compress
        || opt.complement
        || opt.json
    {
        runtime_error("StreamOpt supports solely forward fields, join and single-character delimiters");
    }
    let mut prev: Option<(i64, i64)> = None;
    for b in bounds_iter(&opt.bounds) {
        if !positive(b.l) || !positive(b.r) {
            runtime_error("Bounds cannot be converted to ForwardBounds");
        }
        let l = b.left();
        if let Some((pl, pr)) = prev {
            if l <= pl || l < pr {
                runtime_error("Bounds cannot be converted to ForwardBounds");
            }
        }
        prev = Some((l, right_value(b.r)));
    }
}

fn stream_fields(opt: &Opt, mut records: Records, out: &mut Out) {
    let delim = opt.delimiter[0];
    let join_delim: Vec<u8> = match &opt.replace {
        Some(r) => r.clone(),
        None => vec![delim],
    };
    let mut fields: Vec<(usize, usize)> = Vec::new();
    while let Some(line) = records.next_record() {
        fields.clear();
        let mut start = 0;
        for p in memchr::memchr_iter(delim, line) {
            fields.push((start, p));
            start = p + 1;
        }
        fields.push((start, line.len()));
        let n = fields.len() as i64;
        let field = |k: i64| -> &[u8] {
            let (s, e) = fields[(k - 1) as usize];
            &line[s..e]
        };
        // next field that can still be emitted
        let mut next: i64 = 1;
        let mut exhausted = false;
        for item in &opt.bounds {
            let b = match item {
                Item::Filler(f) => {
                    out.write(f);
                    continue;
                }
                Item::Bound(b) => b,
            };
            let fallback = b.fallback.as_ref().or(opt.fallback_oob.as_ref());
            let l = b.left();
            if b.is_single() {
                let empty_first = l == 1 && fields[0].0 == fields[0].1;
                if exhausted || l < next || l > n || empty_first {
                    if empty_first || l > n {
                        exhausted = true;
                    }
                    match fallback {
                        Some(fb) => out.write(fb),
                        None => out.fail(&format!("Out of bounds: {}", l)),
                    }
                    continue;
                }
                if opt.join && l > 1 {
                    out.write(&join_delim);
                }
                out.write(field(l));
                next = l + 1;
                continue;
            }
            // range
            if exhausted || l > n {
                match b.r {
                    Side::Continue => {}
                    Side::Some(_) => match fallback {
                        Some(fb) => out.write(fb),
                        None => out.fail(&format!("Out of bounds: {}", l)),
                    },
                }
                continue;
            }
            let start = l.max(next);
            let (end, complete) = match b.r {
                Side::Continue => (n, true),
                Side::Some(r) => (r.min(n), r <= n),
            };
            let mut k = start;
            while k <= end {
                if (opt.join && k > 1) || (!opt.join && k > l) {
                    out.write(&join_delim);
                }
                out.write(field(k));
                k += 1;
            }
            if start <= end {
                next = end + 1;
            }
            if !complete {
                exhausted = true;
                match fallback {
                    Some(fb) => out.write(fb),
                    None => out.fail(&format!("Out of bounds: {}", l)),
                }
            }
        }
        out.byte(opt.eol);
    }
    out.flush();
}
