    elif mode < 0.95: args += ['-l', rlist()]
    if random.random() < 0.85:
        if random.random() < 0.8:
            args += ['-d', random.choice(['-', '-', ',', ' ', '--', 'ab', '1', ''])]
        else:
            args += ['-e', random.choice(['-', '-+', '\\d', ' +', '[,-]', 'b|', 'a*', '\\s'])]
