    if random.random() < 0.15: args += ['-r', random.choice(['+', '', '<$0>', '--'])]
    if random.random() < 0.1: args += ['-t', random.choice(['l', 'r', 'b', 'B'])]
    if random.random() < 0.1: args += ['--fallback-oob', random.choice(['Q', '', 'a-b'])]
    if random.random() < 0.05: args += ['-M', '1']
    random.shuffle_args = None
    return args
ok = 0
fails = 0
