            "/workspace/src/cut_str.rs:241:18",
            &format!("range end index {} out of range for slice of length {}", e, len),
        );
    }
    if s > e {
        fake_panic(
            "/workspace/src/cut_str.rs:241:18",
            &format!("slice index starts at {} but ends at {}", s, e),
        );
    }
    &line[s..e]
