/// Resolve a bound to a byte range of the line (strict version).
///
/// `stale` is Some when negative sides must be resolved against the fields
/// of a previous line (Some(None) when no such line exists yet).
fn resolve_bytes(
    b: &UserBounds,
    fields: &[(usize, usize)],
    stale: Option<Option<(&[(usize, usize)], usize)>>,
) -> Result<(usize, usize), ResolveError> {
    let n = fields.len();
    let lookup = |v: i64| -> Result<(usize, usize), ResolveError> {
        let a = v.unsigned_abs() as usize;
        if v > 0 {
            if a > n {
                return Err(ResolveError::OutOfBounds(v));
            }
            return Ok(fields[a - 1]);
        }
        match stale {
            None => {
                if a > n {
                    return Err(ResolveError::OutOfBounds(v));
                }
                Ok(fields[n - a])
            }
            Some(None) => Err(ResolveError::OutOfBounds(v)),
            Some(Some((buf, count))) => {
                if a > count {
                    return Err(ResolveError::OutOfBounds(v));
                }
                Ok(buf[count - a])
            }
        }
    };
    let start = match b.l {
        Side::Some(v) => lookup(v)?.0,
        Side::Continue => fields[0].0,
    };
    let end = match b.r {
        Side::Some(v) => lookup(v)?.1,
        Side::Continue => fields[n - 1].1,
    };
    if start > end {
        return Err(ResolveError::LeftGreater);
    }
    Ok((start, end))
}
